previewCss:
.darma-loader-thermometer-fill {
  position: relative;
  width: 16px;
  height: 52px;
}
.darma-loader-thermometer-fill::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 10px;
  height: 42px;
  margin-left: -5px;
  border: 2px solid #c7d2fe;
  border-radius: 6px;
  box-sizing: border-box;
}
.darma-loader-thermometer-fill::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 16px;
  height: 16px;
  margin-left: -8px;
  border-radius: 50%;
  background: var(--loader-color, #6366f1);
}
.darma-loader-thermometer-fill i {
  position: absolute;
  bottom: 6px;
  left: 50%;
  width: 6px;
  margin-left: -3px;
  border-radius: 3px;
  background: var(--loader-color, #6366f1);
  animation: darma-loader-thermometer-fill-merc 1.6s ease-in-out infinite;
}
@keyframes darma-loader-thermometer-fill-merc {
  0%, 100% { height: 8px; }
  50% { height: 36px; }
}

